      const d = ['M12 3V6', 'M18.3635 5.63672L16.2422 7.75804', 'M21 12L18 12', 'M18.3635 18.3635L16.2422 16.2422', 'M12 18V21', 'M7.75804 16.2422L5.63672 18.3635', 'M6 12L3 12', 'M7.75804 7.75804L5.63672 5.63672'];
      const s = auSvg('<g>' + d.map((p) => `<path d="${p}" stroke-linecap="round"/>`).join('') + '</g>', 'size-5', '');
