        anim(g, [{ scale: 1 }, { scale: 0.9 }, { scale: 1.1 }, { scale: 1 }], { duration: 600, easing: EASE_IO });
        anim(g.firstChild, [{ fillOpacity: 0 }, { fillOpacity: 1 }], { duration: 300, delay: 200, fill: 'forwards' });
