            const item = (node, i) => { node.className = 'inline-block'; anim(node, [{ opacity: 0, filter: 'blur(8px)' }, { opacity: 1, filter: 'blur(0px)' }], { duration: duration * 1000, delay: (delay + i * stagger) * 1000, easing: EASE_OUT, fill: 'backwards' }); return node; };
            if (mode === 'letter') for (const ch of w.split('')) ww.append(item(mk('span', '', esc(ch)), ci++));
